 if(has('bigeyes'))for(const side of [-1,1]){ball(0xd9edb6,side*.25,hy+.24,hz-.15,.19,.2,.17);eyes(side*.25,hy+.26,hz-.3,.04);}
 if(has('gills')&&t.body!=='aquatic')for(const side of [-1,1])for(let i=0;i<3;i++)cone(0xf3ca99,side*.4,hy+i*.12,hz,.12,.33,.1);
 if(has('webfeet')||has('orangefeet')||has('rootfeet'))for(const side of [-1,1])box(has('orangefeet')?0xffc275:c,side*.27,.08,-.2,.35,.12,.45);
 if(has('whiskers'))for(const side of [-1,1])for(const dy of [-.06,.06])box(accent,side*.37,hy-.05+dy,hz-.3,.32,.025,.025);
 if(has('leafcrown')||has('flowercrown')||has('starcrest')||has('starcrown')||has('lightning')||has('lightningwings')||has('crest')||has('roostercrest')||has('flamecrest'))for(let i=0;i<3;i++)m(has('leafcrown')?v.ball:v.gem,has('lightning')||has('starcrest')?0xffdf8b:has('roostercrest')?0xf28b91:0xb2e8b5,(i-1)*.18,hy+.42+(i%2)*.15,hz,.11,.23,.1);
